'use client';

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import Link from 'next/link';
import { dashboardUtils } from '@/lib/storage';

interface DashboardStats {
  totalClients: number;
  totalInvoices: number;
  unpaidInvoices: number;
  monthlyIncome: number;
}

export default function DashboardPage() {
  const [stats, setStats] = useState<DashboardStats>({
    totalClients: 0,
    totalInvoices: 0,
    unpaidInvoices: 0,
    monthlyIncome: 0,
  });
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const loadStats = () => {
      try {
        const dashboardStats = dashboardUtils.getStats();
        setStats(dashboardStats);
      } catch (error) {
        console.error('Error loading dashboard stats:', error);
      } finally {
        setIsLoading(false);
      }
    };

    loadStats();
  }, []);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(amount);
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <h1 className="text-3xl font-bold text-gray-900">Dashboard</h1>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[...Array(4)].map((_, i) => (
            <Card key={i}>
              <CardHeader className="pb-2">
                <div className="h-4 bg-gray-200 rounded animate-pulse"></div>
              </CardHeader>
              <CardContent>
                <div className="h-8 bg-gray-200 rounded animate-pulse"></div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold text-gray-900">Dashboard</h1>
        <div className="flex space-x-3">
          <Button asChild>
            <Link href="/clients/new">Add Client</Link>
          </Button>
          <Button asChild>
            <Link href="/invoices/new">Create Invoice</Link>
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">
              Total Clients
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">
              {stats.totalClients}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              Active clients in system
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">
              Total Invoices
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-900">
              {stats.totalInvoices}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              All time invoices
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">
              Unpaid Invoices
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">
              {stats.unpaidInvoices}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              Require attention
            </p>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-gray-600">
              Monthly Income
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">
              {formatCurrency(stats.monthlyIncome)}
            </div>
            <p className="text-xs text-gray-500 mt-1">
              Current month
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>Quick Actions</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <Button asChild variant="outline" className="w-full justify-start">
              <Link href="/clients">View All Clients</Link>
            </Button>
            <Button asChild variant="outline" className="w-full justify-start">
              <Link href="/invoices">View All Invoices</Link>
            </Button>
            <Button asChild variant="outline" className="w-full justify-start">
              <Link href="/invoices?status=unpaid">View Unpaid Invoices</Link>
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Recent Activity</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-sm text-gray-500 text-center py-8">
              <p>No recent activity</p>
              <p className="mt-1">Start by creating clients and invoices</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Getting Started */}
      {stats.totalClients === 0 && (
        <Card className="border-blue-200 bg-blue-50">
          <CardHeader>
            <CardTitle className="text-blue-900">Getting Started</CardTitle>
          </CardHeader>
          <CardContent className="text-blue-800">
            <p className="mb-4">
              Welcome to your Business Management System! Here's how to get started:
            </p>
            <ol className="list-decimal list-inside space-y-2 text-sm">
              <li>Add your first client using the "Add Client" button</li>
              <li>Create an invoice for your client</li>
              <li>Generate PDF or send via email</li>
              <li>Track payment status and manage your business</li>
            </ol>
            <div className="mt-4 space-x-3">
              <Button asChild size="sm">
                <Link href="/clients/new">Add First Client</Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
