import { Client, Invoice, CreateClientData, CreateInvoiceData, UpdateClientData, UpdateInvoiceData } from './types';

// Storage keys
const CLIENTS_KEY = 'business_app_clients';
const INVOICES_KEY = 'business_app_invoices';
const INVOICE_COUNTER_KEY = 'business_app_invoice_counter';

// Utility functions
const generateId = (): string => {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
};

const generateInvoiceNumber = (): string => {
  if (typeof window === 'undefined') return 'INV-0001';
  
  const counter = parseInt(localStorage.getItem(INVOICE_COUNTER_KEY) || '0') + 1;
  localStorage.setItem(INVOICE_COUNTER_KEY, counter.toString());
  return `INV-${counter.toString().padStart(4, '0')}`;
};

// Client Management Functions
export const clientStorage = {
  getAll: (): Client[] => {
    if (typeof window === 'undefined') return [];
    
    try {
      const data = localStorage.getItem(CLIENTS_KEY);
      if (!data) return [];
      
      const clients = JSON.parse(data);
      return clients.map((client: any) => ({
        ...client,
        createdAt: new Date(client.createdAt),
        updatedAt: new Date(client.updatedAt),
      }));
    } catch (error) {
      console.error('Error loading clients:', error);
      return [];
    }
  },

  getById: (id: string): Client | null => {
    const clients = clientStorage.getAll();
    return clients.find(client => client.id === id) || null;
  },

  create: (data: CreateClientData): Client => {
    const clients = clientStorage.getAll();
    const newClient: Client = {
      id: generateId(),
      ...data,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    
    clients.push(newClient);
    localStorage.setItem(CLIENTS_KEY, JSON.stringify(clients));
    return newClient;
  },

  update: (id: string, data: UpdateClientData): Client | null => {
    const clients = clientStorage.getAll();
    const index = clients.findIndex(client => client.id === id);
    
    if (index === -1) return null;
    
    clients[index] = {
      ...clients[index],
      ...data,
      updatedAt: new Date(),
    };
    
    localStorage.setItem(CLIENTS_KEY, JSON.stringify(clients));
    return clients[index];
  },

  delete: (id: string): boolean => {
    const clients = clientStorage.getAll();
    const filteredClients = clients.filter(client => client.id !== id);
    
    if (filteredClients.length === clients.length) return false;
    
    localStorage.setItem(CLIENTS_KEY, JSON.stringify(filteredClients));
    return true;
  },

  search: (query: string): Client[] => {
    const clients = clientStorage.getAll();
    const lowercaseQuery = query.toLowerCase();
    
    return clients.filter(client =>
      client.name.toLowerCase().includes(lowercaseQuery) ||
      client.email.toLowerCase().includes(lowercaseQuery) ||
      client.companyName.toLowerCase().includes(lowercaseQuery) ||
      client.phone.includes(query)
    );
  },
};

// Invoice Management Functions
export const invoiceStorage = {
  getAll: (): Invoice[] => {
    if (typeof window === 'undefined') return [];
    
    try {
      const data = localStorage.getItem(INVOICES_KEY);
      if (!data) return [];
      
      const invoices = JSON.parse(data);
      return invoices.map((invoice: any) => ({
        ...invoice,
        invoiceDate: new Date(invoice.invoiceDate),
        dueDate: new Date(invoice.dueDate),
        createdAt: new Date(invoice.createdAt),
        updatedAt: new Date(invoice.updatedAt),
        lineItems: invoice.lineItems.map((item: any) => ({
          ...item,
          id: item.id || generateId(),
        })),
      }));
    } catch (error) {
      console.error('Error loading invoices:', error);
      return [];
    }
  },

  getById: (id: string): Invoice | null => {
    const invoices = invoiceStorage.getAll();
    return invoices.find(invoice => invoice.id === id) || null;
  },

  getByClientId: (clientId: string): Invoice[] => {
    const invoices = invoiceStorage.getAll();
    return invoices.filter(invoice => invoice.clientId === clientId);
  },

  create: (data: CreateInvoiceData): Invoice => {
    const invoices = invoiceStorage.getAll();
    
    // Calculate line item totals
    const lineItems = data.lineItems.map(item => ({
      id: generateId(),
      ...item,
      total: (item.quantity * item.rate) + (item.quantity * item.rate * item.tax / 100),
    }));
    
    // Calculate invoice totals
    const subtotal = lineItems.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
    const totalTax = lineItems.reduce((sum, item) => sum + (item.quantity * item.rate * item.tax / 100), 0);
    const total = subtotal + totalTax;
    
    const newInvoice: Invoice = {
      id: generateId(),
      invoiceNumber: generateInvoiceNumber(),
      ...data,
      lineItems,
      subtotal,
      totalTax,
      total,
      status: 'draft',
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    
    invoices.push(newInvoice);
    localStorage.setItem(INVOICES_KEY, JSON.stringify(invoices));
    return newInvoice;
  },

  update: (id: string, data: UpdateInvoiceData): Invoice | null => {
    const invoices = invoiceStorage.getAll();
    const index = invoices.findIndex(invoice => invoice.id === id);
    
    if (index === -1) return null;
    
    let updatedInvoice = { ...invoices[index] };
    
    // Update basic fields
    Object.keys(data).forEach(key => {
      if (key !== 'lineItems' && data[key as keyof UpdateInvoiceData] !== undefined) {
        (updatedInvoice as any)[key] = data[key as keyof UpdateInvoiceData];
      }
    });
    
    // Update line items if provided
    if (data.lineItems) {
      const lineItems = data.lineItems.map(item => ({
        id: generateId(),
        ...item,
        total: (item.quantity * item.rate) + (item.quantity * item.rate * item.tax / 100),
      }));
      
      const subtotal = lineItems.reduce((sum, item) => sum + (item.quantity * item.rate), 0);
      const totalTax = lineItems.reduce((sum, item) => sum + (item.quantity * item.rate * item.tax / 100), 0);
      const total = subtotal + totalTax;
      
      updatedInvoice = {
        ...updatedInvoice,
        lineItems,
        subtotal,
        totalTax,
        total,
      };
    }
    
    updatedInvoice.updatedAt = new Date();
    invoices[index] = updatedInvoice;
    
    localStorage.setItem(INVOICES_KEY, JSON.stringify(invoices));
    return updatedInvoice;
  },

  delete: (id: string): boolean => {
    const invoices = invoiceStorage.getAll();
    const filteredInvoices = invoices.filter(invoice => invoice.id !== id);
    
    if (filteredInvoices.length === invoices.length) return false;
    
    localStorage.setItem(INVOICES_KEY, JSON.stringify(filteredInvoices));
    return true;
  },

  updateStatus: (id: string, status: Invoice['status']): Invoice | null => {
    return invoiceStorage.update(id, { status });
  },
};

// Dashboard utility functions
export const dashboardUtils = {
  getStats: () => {
    const clients = clientStorage.getAll();
    const invoices = invoiceStorage.getAll();
    
    const totalClients = clients.length;
    const totalInvoices = invoices.length;
    const unpaidInvoices = invoices.filter(inv => inv.status !== 'paid').length;
    
    // Calculate monthly income (current month)
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    const monthlyIncome = invoices
      .filter(inv => 
        inv.status === 'paid' &&
        inv.invoiceDate.getMonth() === currentMonth &&
        inv.invoiceDate.getFullYear() === currentYear
      )
      .reduce((sum, inv) => sum + inv.total, 0);
    
    return {
      totalClients,
      totalInvoices,
      unpaidInvoices,
      monthlyIncome,
    };
  },
};

// Export utility functions
export const exportUtils = {
  generateCSV: (data: any[], headers: string[]): string => {
    const csvContent = [
      headers.join(','),
      ...data.map(row => 
        headers.map(header => {
          const value = row[header];
          // Escape commas and quotes in CSV
          if (typeof value === 'string' && (value.includes(',') || value.includes('"'))) {
            return `"${value.replace(/"/g, '""')}"`;
          }
          return value || '';
        }).join(',')
      )
    ].join('\n');
    
    return csvContent;
  },

  downloadFile: (content: string, filename: string, mimeType: string) => {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  },
};
